<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,initialUser?:string}>()
const users=ref<Row[]>([]),profiles=ref<Row[]>([]),shares=ref<Row[]>([]),services=ref<Row[]>([]),tab=ref('shares'),editing=ref<Row|null>(null),removing=ref<Row|null>(null),error=ref(''),notice=ref(''),busy=ref(false),url=ref(''),format=ref('auto'),diagnostic=ref<Row|null>(null),diagnosticID=ref('')
const fallbackFormats=[{id:'sing-box',name:'sing-box JSON'},{id:'mihomo',name:'Mihomo'},{id:'shadowrocket',name:'Shadowrocket URI'},{id:'xray',name:'Xray JSON'}]
const formats=ref(fallbackFormats), catalog=ref<Row[]>([])
const formatted=computed(()=>url.value?url.value+(format.value==='auto'?'':'?client='+format.value+(['shadowrocket','base64','v2rayng-uri','nekobox-uri','naive-proxy'].includes(format.value)?'&policy=nodes-only':'')):'')
async function reload(){try{catalog.value=await props.api('client-catalog');if(catalog.value.length)formats.value=catalog.value.map(c=>({id:c.id,name:c.name+(c.full_config?' · 完整策略':' · 仅节点')}))}catch{};[users.value,profiles.value,shares.value,services.value]=await Promise.all(['proxy-users','client-profiles','subscriptions','live'].map(p=>props.api(p)))}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function create(){editing.value=tab.value==='shares'?{name:'',user_id:props.initialUser||users.value.find(u=>u.active)?.id||'',profile_id:'',days:30,service_ids:[],mode:'user'}:{name:'',format:'sing-box',local_port:1080,selection:'select',test_url:'https://www.gstatic.com/generate_204',extra_text:'{}',version:0}}
onMounted(()=>void run(async()=>{await reload();if(props.initialUser){create();editing.value!.name=(users.value.find(u=>u.id===props.initialUser)?.name??'用户')+'的订阅'}}))
onUnmounted(()=>url.value='')
function edit(row:Row){editing.value={...JSON.parse(JSON.stringify(row)),expires_at:row.expires_at?.slice(0,10),mode:row.user_id?'user':'shared',service_ids:row.service_ids??[],extra_text:row.extra_text||JSON.stringify(row.extra_config??{},null,2)}}
function save(){const v=editing.value;if(!v)return;void run(async()=>{if(tab.value==='templates'){const {id}=v;const body={name:v.name,format:v.format,local_port:v.local_port,selection:v.selection,test_url:v.test_url,extra_text:v.extra_text??JSON.stringify(v.extra_config??{},null,2),version:v.version};await props.api('client-profiles'+(id?'/'+id:''),id?'PUT':'POST',body)}else if(v.id){await props.api('subscriptions/'+v.id,'PUT',{name:v.name,profile_id:v.profile_id??'',expires_at:new Date(v.expires_at+'T23:59:59').toISOString(),version:v.version,user_id:v.mode==='user'?v.user_id:'',service_ids:v.mode==='shared'?v.service_ids:[]})}else{const r=await props.api('subscriptions','POST',{name:v.name,user_id:v.mode==='user'?v.user_id:'',service_ids:v.mode==='shared'?v.service_ids:[],profile_id:v.profile_id,days:v.days});url.value=r.url;format.value=profiles.value.find(p=>p.id===v.profile_id)?.format??'auto'};editing.value=null;notice.value='已保存';await reload()})}
function link(r:Row,rotate=false){void run(async()=>{const result=await props.api('subscriptions/'+r.id+(rotate?'/rotate':'/link'),rotate?'POST':'GET',rotate?{}:undefined);url.value=result.url;format.value=profiles.value.find(p=>p.id===r.profile_id)?.format??'auto'})}
async function copy(){try{await navigator.clipboard.writeText(formatted.value);notice.value='已复制所选客户端格式的链接'}catch{error.value='请选中下方链接手动复制'}}
function remove(){const r=removing.value;if(!r)return;void run(async()=>{await props.api((tab.value==='shares'?'subscriptions':'client-profiles')+'/'+r.id,'DELETE');removing.value=null;url.value='';await reload()})}
function inspect(id:string){diagnosticID.value=id;void run(async()=>{diagnostic.value=await props.api('subscriptions/'+id+'/usage')})}
function inspectConfig(){void run(async()=>{diagnostic.value=await props.api('subscriptions/'+diagnosticID.value+'/config'+(format.value==='auto'?'':'?client='+format.value+(['shadowrocket','base64','v2rayng-uri','nekobox-uri','naive-proxy'].includes(format.value)?'&policy=nodes-only':'')))})}
function example(){if(!editing.value)return;editing.value.extra_text=editing.value.format==='mihomo'?'# 客户端规则，节点由系统生成\nmode: rule\nipv6: true\nrules:\n  - DOMAIN-SUFFIX,lan,DIRECT\n  - MATCH,PROXY\n':JSON.stringify(editing.value.format==='sing-box'?{log:{level:'warn'},route:{rules:[{ip_is_private:true,outbound:'direct'}],final:'proxy'}}:editing.value.format==='xray'?{log:{loglevel:'warning'}}:{},null,2)}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><h2>客户端订阅</h2><p class="muted">选择用户即可分享其获授权的协议；客户端格式可手动切换。模板是可选的客户端设置。</p></div><button class="primary" @click="create">＋ {{tab==='shares'?'添加订阅':'添加模板'}}</button></div><nav class="subnav"><button class="secondary" :class="{active:tab==='shares'}" @click="tab='shares'">订阅链接</button><button class="secondary" :class="{active:tab==='templates'}" @click="tab='templates'">客户端配置模板</button></nav><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<div v-if="url" class="share-box"><div class="fields"><label>客户端格式<select v-model="format"><option value="auto">自动识别客户端 / 模板默认</option><option v-for="f in formats" :key="f.id" :value="f.id">{{f.name}}</option></select></label><label>订阅链接<input :value="formatted" readonly @focus="($event.target as HTMLInputElement).select()"></label></div><button class="secondary" @click="copy">复制订阅链接</button><button class="text-button" @click="url=''">收起链接</button><p class="muted">完整配置自动带入用户与客户端策略；仅节点格式无法携带规则。显式选择客户端时自动筛选兼容节点。SS / Snell 共享流量不计入个人额度。</p></div>
<div class="table-scroll"><table v-if="tab==='shares'"><thead><tr><th>订阅</th><th>所属用户 / 模板</th><th>有效期</th><th>操作</th></tr></thead><tbody><tr v-for="s in shares" :key="s.id"><td>{{s.name}}<small class="block-muted">{{s.revoked_at?'已撤销':s.active===false?'已到期':'有效'}}</small></td><td>{{users.find(u=>u.id===s.user_id)?.name??'共享密钥订阅'}}<small class="block-muted">{{profiles.find(p=>p.id===s.profile_id)?.name??'默认客户端设置'}}</small></td><td>{{new Date(s.expires_at).toLocaleDateString()}}</td><td class="row-actions"><button class="text-button" :disabled="!!s.revoked_at" @click="link(s)">分享链接</button><button class="text-button" :disabled="!!s.revoked_at" @click="inspect(s.id)">用量 / 客户端配置</button><button class="text-button" :disabled="!!s.revoked_at" @click="edit(s)">编辑</button><button class="text-button" :disabled="!!s.revoked_at" @click="removing={...s,rotate:true}">重置链接</button><button class="text-button danger" @click="removing=s">删除</button></td></tr></tbody></table><table v-else><thead><tr><th>模板</th><th>客户端 / 策略</th><th>本地端口</th><th>操作</th></tr></thead><tbody><tr v-for="p in profiles" :key="p.id"><td>{{p.name}}</td><td>{{p.format}} · {{p.selection}}</td><td>127.0.0.1:{{p.local_port}}</td><td><button class="text-button" @click="edit(p)">编辑</button><button class="text-button danger" @click="removing=p">删除</button></td></tr></tbody></table></div><p v-if="!(tab==='shares'?shares:profiles).length" class="console-empty">{{tab==='shares'?'还没有订阅。添加订阅并选择用户，即可生成域名链接。':'未设置模板时使用默认客户端配置。'}}</p></section>
<div v-if="editing" class="modal-backdrop" @keydown.esc="editing=null"><form class="modal" role="dialog" aria-modal="true" aria-label="订阅配置" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'编辑':'添加'}}{{tab==='shares'?'订阅':'客户端模板'}}</h2><button type="button" class="secondary" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><div class="fields"><label>名称<input v-model="editing.name" required maxlength="100"></label><template v-if="tab==='shares'"><label >授权方式<select v-model="editing.mode"><option value="user">用户权限（推荐）</option><option value="shared">共享密钥配置（SS / Snell 等）</option></select></label><label v-if="editing.mode==='user'">所属用户<select v-model="editing.user_id" required><option value="">选择已分配权限的用户</option><option v-for="u in users.filter(u=>u.enabled!==false&&new Date(u.expires_at)>new Date())" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>客户端设置<select v-model="editing.profile_id"><option value="">默认设置</option><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}} · {{p.format}}</option></select></label><label v-if="editing.id">有效期至<input v-model="editing.expires_at" type="date" required></label><label v-else>有效天数<input v-model.number="editing.days" type="number" min="1" max="365" required></label></template><template v-else><label>客户端格式<select v-model="editing.format"><option v-for="f in formats" :key="f.id" :value="f.id">{{f.name}}</option></select></label><label>本地端口<input v-model.number="editing.local_port" type="number" min="1024" max="65535" required></label><label>节点策略<select v-model="editing.selection"><option value="select">手动选择</option><option value="urltest">延迟自动选择</option></select></label><label>连通性测试<select v-model="editing.test_url"><option>https://www.gstatic.com/generate_204</option><option>https://cp.cloudflare.com/generate_204</option></select></label></template></div><div v-if="tab==='shares'&&editing.mode==='shared'" class="choice-list"><label v-for="s in services.filter(s=>!s.managed_users&&!s.delete_requested_at&&!['frpc','frps'].includes(s.kind))" :key="s.id"><input v-model="editing.service_ids" type="checkbox" :value="s.id">{{s.name}} · {{s.kind}}</label><p class="muted">共享密钥无法单独撤销某一用户；需要轮换协议密钥。</p></div><template v-if="tab==='templates'"><h3>手动客户端配置 · JSON / YAML</h3><p class="muted">编辑 DNS、路由规则、日志等；订阅节点与用户凭据由系统生成。手动客户端入站只允许回环监听。配置仅用于此模板选定格式。</p><button type="button" class="secondary" @click="example">填入示例</button><label>客户端配置覆盖<textarea v-model="editing.extra_text" rows="14" class="native-preview" spellcheck="false" maxlength="32768"></textarea></label></template><p v-if="editing.id&&tab==='shares'" class="form-note">修改绑定用户后，客户端需要更新订阅；旧共享密钥的撤销仍需轮换节点凭据。</p><p class="muted">用户订阅会随用户组权限变化；停用、离线或尚未应用的入站不会发布。</p></div><div class="modal-footer"><button class="secondary" type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy">保存</button></div></form></div>
<div v-if="diagnostic" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="订阅用量诊断"><div class="modal-heading"><h2>订阅用量与客户端配置</h2><button class="secondary" @click="diagnostic=null">关闭</button></div><div class="form-content"><p>{{diagnostic.notice}}</p><p class="form-note">Clash 用量卡片在更新订阅时读取响应头；共享订阅没有个人额度。0 B 也可能是此身份尚未产生流量。</p><label>预览客户端格式<select v-model="format"><option value="auto">自动 / 模板默认</option><option v-for="f in formats" :key="f.id" :value="f.id">{{f.name}}</option></select></label><button class="secondary" :disabled="busy" @click="inspectConfig">查看生成配置与响应头</button><p v-if="error" class="error">{{error}}</p><pre class="native-preview">{{JSON.stringify(diagnostic,null,2)}}</pre><p class="muted">凭据已隐藏。修改客户端参数请编辑该订阅关联的客户端模板；VPS 入站在协议配置中修改。</p></div></section></div><div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="确认订阅操作"><div class="form-content"><h2>{{removing.rotate?'重置链接':'删除'}} {{removing.name}}？</h2><p>{{removing.rotate?'旧链接将立即失效，需要重新分发。':tab==='shares'?'立即停止此链接下载。已导入的代理凭据仍有效，撤销访问请停用用户或轮换凭据。':'关联订阅将改用默认客户端设置。'}}</p><p v-if="error" class="error" role="alert">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="removing.rotate?(link(removing,true),removing=null):remove()">确认</button></div></section></div></template>
